#!/bin/bash
# Verifier for a skill-eval task (generated by harbor-mod).
#
# F1 skill load+invoke proof (from the agent trajectory under /logs/agent) plus
# the single-call LLM judge (judge.py). These are behaviour evals, so there is
# no deterministic mechanical check; the reward comes from the judge unless the
# F1 proof fails.
set -uo pipefail

# --- F1: skill load + invoke proof (agent trajectory under /logs/agent) -------
# Enforced unless SKILL_EVAL_ENFORCE_SKILL_USE=false (e.g. without-skill jobs).
SKILL_OK=1
if [ "${SKILL_EVAL_ENFORCE_SKILL_USE:-true}" = "true" ]; then
  SKILL_NAME="${SKILL_EVAL_SKILL_NAME:-{{SKILL_NAME}}}"
  if [ -d /logs/agent ] && find /logs/agent -type f -name '*.jsonl' | grep -q .; then
    # load: skill context injected into the user turn
    if ! grep -rq '<skill-context' /logs/agent 2>/dev/null; then
      SKILL_OK=0
    fi
    # invoke: at least one tool call to the `skill` tool
    if ! grep -rq '"name" *: *"skill"' /logs/agent 2>/dev/null; then
      SKILL_OK=0
    fi
  fi
fi

if [ "$SKILL_OK" -eq 0 ]; then
  echo 0 > /logs/verifier/reward.txt
  echo "skill_use_ok=$SKILL_OK" > /logs/verifier/reason.txt
  exit 0
fi

# --- LLM judge (single call via judge.py) -------------------------------------
JUDGE_TOKEN="${OPENAI_API_KEY:-${COPILOT_GITHUB_TOKEN:-${GH_TOKEN:-${GITHUB_TOKEN:-}}}}"
if [ -n "$JUDGE_TOKEN" ]; then
  export PATH="$HOME/.local/bin:$PATH"
  if ! command -v uv >/dev/null 2>&1; then
    curl -LsSf https://astral.sh/uv/install.sh | sh
    export PATH="$HOME/.local/bin:$PATH"
  fi
  # Recursive workspace packet: judge.py reads the produced files plus the
  # Copilot CLI transcript under /logs/agent.
  mkdir -p /logs/artifacts
  {
    for f in $(find /workspace -type f -not -path '*/.agents/*' -not -path '*/.git/*' | sort); do
      printf '
--- %s ---

' "$f"
      cat "$f"
    done
  } > /logs/artifacts/workspace-packet.md 2>/dev/null || true

  uv run --no-project --with litellm python /tests/judge.py \
    --rubric /tests/rubric.json \
    --transcript /logs/agent/copilot-cli.txt \
    --packet /logs/artifacts/workspace-packet.md \
    --output /logs/verifier/reward.json \
    --reason-output /logs/verifier/reason.txt \
    || true

  if [ -f /logs/verifier/reward.json ]; then
    python3 -c 'import json,sys; d=json.load(open("/logs/verifier/reward.json")); print(d["reward"])' \
      > /logs/verifier/reward.txt 2>/dev/null \
      || echo 0 > /logs/verifier/reward.txt
  else
    echo 0 > /logs/verifier/reward.txt
  fi
else
  echo 1 > /logs/verifier/reward.txt
fi
